ALTER TABLE public.ride_settings ADD COLUMN ztrip_dispatch_email text NOT NULL DEFAULT 'twolken@ztrip.com', ADD COLUMN ztrip_dispatch_enabled boolean NOT NULL DEFAULT false, ADD COLUMN ztrip_email_on_changes boolean NOT NULL DEFAULT true, ADD COLUMN ztrip_email_ride_home boolean NOT NULL DEFAULT false;
CREATE FUNCTION public.validate_ztrip_dispatch_settings() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.ztrip_dispatch_email:=lower(btrim(NEW.ztrip_dispatch_email)); IF length(NEW.ztrip_dispatch_email)>254 OR NEW.ztrip_dispatch_email !~ '^[A-Za-z0-9.!#$%&*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN RAISE EXCEPTION 'Enter one valid dispatch email address'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_ztrip_dispatch_settings BEFORE INSERT OR UPDATE OF ztrip_dispatch_email ON public.ride_settings FOR EACH ROW EXECUTE FUNCTION public.validate_ztrip_dispatch_settings();
CREATE FUNCTION public.guard_ztrip_dispatch_events() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.event_type IN ('ztrip_dispatch_event','ztrip_email_claimed','ztrip_emailed') OR (NEW.event_type='note' AND NEW.note='ztrip_email_failed') THEN IF coalesce(auth.role(),'')<>'service_role' AND current_setting('uwazi.ztrip_internal',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'Dispatch email events are server managed'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_ztrip_dispatch_events BEFORE INSERT ON public.ride_events FOR EACH ROW EXECUTE FUNCTION public.guard_ztrip_dispatch_events();
CREATE UNIQUE INDEX ztrip_dispatch_one_event_claim ON public.ride_events(request_id,note) WHERE event_type='ztrip_email_claimed';
CREATE FUNCTION public.ztrip_dispatch_fingerprint(_ride public.ride_requests) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT md5(jsonb_build_array(_ride.ride_day,_ride.pickup_time,_ride.pickup_address,_ride.zip,_ride.destination_site_id,_ride.needs_destination)::text); $$;
REVOKE ALL ON FUNCTION public.ztrip_dispatch_fingerprint(public.ride_requests) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ztrip_dispatch_fingerprint(public.ride_requests) TO service_role;
CREATE FUNCTION public.dispatch_ztrip_ride_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.ride_settings; kind text; changed text[]:=ARRAY[]::text[]; event_id uuid; info jsonb; job_token text; old_day date; old_time time; BEGIN SELECT * INTO s FROM public.ride_settings WHERE id=true; IF NOT s.ztrip_dispatch_enabled OR NEW.provider IS DISTINCT FROM 'ztrip' THEN RETURN NEW; END IF; IF TG_OP='INSERT' THEN IF NEW.status NOT IN ('requested','booked') OR NEW.source NOT IN ('web','phone') THEN RETURN NEW; END IF; kind:='new'; ELSE IF NOT EXISTS(SELECT 1 FROM public.ride_events WHERE request_id=NEW.id AND event_type='ztrip_emailed' AND note LIKE 'new|%') THEN RETURN NEW; END IF; old_day:=OLD.ride_day; old_time:=OLD.pickup_time; IF NEW.status='cancelled' AND OLD.status IS DISTINCT FROM NEW.status AND s.ztrip_email_on_changes THEN kind:='cancelled'; ELSIF NEW.status IN ('requested','booked','riding') THEN IF NEW.ride_day IS DISTINCT FROM OLD.ride_day THEN changed:=array_append(changed,'Pickup day'); END IF; IF NEW.pickup_time IS DISTINCT FROM OLD.pickup_time THEN changed:=array_append(changed,'Pickup time'); END IF; IF NEW.pickup_address IS DISTINCT FROM OLD.pickup_address OR NEW.zip IS DISTINCT FROM OLD.zip THEN changed:=array_append(changed,'Pickup address'); END IF; IF NEW.destination_site_id IS DISTINCT FROM OLD.destination_site_id OR NEW.needs_destination IS DISTINCT FROM OLD.needs_destination THEN changed:=array_append(changed,'Voting place'); END IF; IF cardinality(changed)>0 AND s.ztrip_email_on_changes THEN kind:='changed'; ELSIF NEW.trip_stage=5 AND OLD.trip_stage IS DISTINCT FROM 5 AND NEW.round_trip AND NEW.status='riding' AND s.ztrip_email_ride_home THEN kind:='home'; END IF; END IF; END IF; IF kind IS NULL THEN RETURN NEW; END IF; info:=jsonb_build_object('kind',kind,'changed',changed,'oldDay',old_day,'oldTime',old_time,'fingerprint',public.ztrip_dispatch_fingerprint(NEW)); BEGIN PERFORM set_config('uwazi.ztrip_internal','yes',true); INSERT INTO public.ride_events(request_id,event_type,note) VALUES(NEW.id,'ztrip_dispatch_event',info::text) RETURNING id INTO event_id; PERFORM set_config('uwazi.ztrip_internal','no',true); SELECT token INTO job_token FROM public.system_job_token WHERE id=true; IF job_token IS NULL THEN RAISE EXCEPTION 'Dispatch unavailable'; END IF; PERFORM net.http_post(url:='https://zigemhmhbzegwbgvvmpc.supabase.co/functions/v1/ztrip-dispatch-email',headers:=jsonb_build_object('Content-Type','application/json','x-ztrip-dispatch-token',job_token),body:=jsonb_build_object('action','event','eventId',event_id),timeout_milliseconds:=5000); EXCEPTION WHEN OTHERS THEN BEGIN PERFORM set_config('uwazi.ztrip_internal','yes',true); INSERT INTO public.ride_events(request_id,event_type,note) VALUES(NEW.id,'note','ztrip_email_failed'); PERFORM set_config('uwazi.ztrip_internal','no',true); EXCEPTION WHEN OTHERS THEN NULL; END; END; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.dispatch_ztrip_ride_event() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER ztrip_dispatch_ride_insert AFTER INSERT ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.dispatch_ztrip_ride_event(); CREATE TRIGGER ztrip_dispatch_ride_change AFTER UPDATE OF status,ride_day,pickup_time,pickup_address,zip,destination_site_id,needs_destination,trip_stage ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.dispatch_ztrip_ride_event();
CREATE FUNCTION public.claim_ztrip_dispatch_email(_event_id uuid DEFAULT NULL,_sample_actor uuid DEFAULT NULL,_sample_id uuid DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.ride_events; r public.ride_requests; s public.ride_settings; info jsonb; n integer; BEGIN IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Server only'; END IF; PERFORM pg_advisory_xact_lock(7241331); IF _sample_actor IS NOT NULL THEN IF _event_id IS NOT NULL OR _sample_id IS NULL OR NOT public.is_admin(_sample_actor) THEN RETURN 'forbidden'; END IF; IF EXISTS(SELECT 1 FROM public.ride_admin_log WHERE action='ztrip_sample_claimed' AND target_id=_sample_id) THEN RETURN 'duplicate'; END IF; ELSE SELECT * INTO e FROM public.ride_events WHERE id=_event_id AND event_type='ztrip_dispatch_event'; IF NOT FOUND THEN RETURN 'skipped'; END IF; SELECT * INTO s FROM public.ride_settings WHERE id=true; IF NOT s.ztrip_dispatch_enabled THEN RETURN 'disabled'; END IF; SELECT * INTO r FROM public.ride_requests WHERE id=e.request_id; IF NOT FOUND OR r.provider IS DISTINCT FROM 'ztrip' THEN RETURN 'skipped'; END IF; info:=e.note::jsonb; IF info->>'fingerprint' IS DISTINCT FROM public.ztrip_dispatch_fingerprint(r) THEN RETURN 'superseded'; END IF; IF info->>'kind'='new' THEN IF r.status NOT IN ('requested','booked') OR EXISTS(SELECT 1 FROM public.ride_events WHERE request_id=r.id AND event_type='ztrip_email_claimed' AND note LIKE 'new|%') THEN RETURN 'duplicate'; END IF; ELSE IF NOT EXISTS(SELECT 1 FROM public.ride_events WHERE request_id=r.id AND event_type='ztrip_emailed' AND note LIKE 'new|%') THEN RETURN 'skipped'; END IF; IF info->>'kind' IN ('changed','cancelled') AND NOT s.ztrip_email_on_changes THEN RETURN 'disabled'; END IF; IF info->>'kind'='home' AND (NOT s.ztrip_email_ride_home OR r.trip_stage<>5 OR NOT r.round_trip OR r.status<>'riding') THEN RETURN 'disabled'; END IF; END IF; IF EXISTS(SELECT 1 FROM public.ride_events WHERE request_id=r.id AND event_type='ztrip_email_claimed' AND note=(info->>'kind')||'|'||_event_id::text) THEN RETURN 'duplicate'; END IF; END IF; SELECT (SELECT count(*) FROM public.ride_events WHERE event_type='ztrip_email_claimed' AND created_at>now()-interval '1 hour')+(SELECT count(*) FROM public.ride_admin_log WHERE action='ztrip_sample_claimed' AND created_at>now()-interval '1 hour') INTO n; IF n>=30 THEN RETURN 'limited'; END IF; IF _sample_actor IS NOT NULL THEN INSERT INTO public.ride_admin_log(actor,action,target_id,note) VALUES(_sample_actor,'ztrip_sample_claimed',_sample_id,'dispatch sample'); ELSE INSERT INTO public.ride_events(request_id,event_type,note) VALUES(r.id,'ztrip_email_claimed',(info->>'kind')||'|'||_event_id::text); END IF; RETURN 'claimed'; END $$;
REVOKE ALL ON FUNCTION public.claim_ztrip_dispatch_email(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_ztrip_dispatch_email(uuid,uuid,uuid) TO service_role;